namespace ZteImeiStudio.Windows;

internal sealed record OperationHelpSection(string Title, string Body, string? Commands = null);
internal sealed record OperationHelpTopic(string Title, string AccessibleName, string Introduction,
    IReadOnlyList<OperationHelpSection> Sections);

/// <summary>
/// User-facing account of the implemented Windows workflows. Keep this aligned
/// with Core/OnboardingEngine.cs, Core/ImeiEngine*.cs and the pinned device payloads.
/// </summary>
internal static class OperationHelpContent
{
    public static OperationHelpTopic FirmwareAdaptation { get; } = new(
        "Сбор данных для адаптации прошивки", "Что входит в данные для адаптации прошивки",
        "Сохраняются текущий бинарник экранного интерфейса, его языковые файлы и сценарий запуска экранного интерфейса, безопасные сведения о режиме агента и очищенный журнал программы. Настройки, пароли, ключи, IMEI, SIM/eSIM-профили, сценарий запуска агента и полный образ флеш-памяти не собираются. Файлы читаются по текущему SSH без изменений на модеме. Размеры и SHA-256 проверяются; недоступные обязательные файлы отмечаются как неполный сбор. Если файл или устройство изменились во время чтения, итоговый ZIP не создаётся. Архив предназначен для анализа совместимости и сам по себе не разрешает установку или запись. Если доступна проверенная копия нашей русификации, её исходные файлы тоже включаются.", []);
    public static OperationHelpTopic DiagnosticAdb { get; } = new(
        "ADB для диагностики", "Подробно о включении диагностического ADB", "Первоначальное включение ADB выполняется флажком в настройках подключения. При работающем SSH используется отдельное проверенное управление состоянием ADB; этот путь не устанавливает агент или SSH.",
        [
            new("1. Проверка доступа и модема",
                "Проверяются незавершённые операции и идентичность. Уже работающий root USB ADB подтверждается повторно и сохраняется без переключения USB, бэкапа или перезагрузки. Обычные операции программы продолжают работать по SSH."),
            new("2. Последовательное включение",
                "Известный ключ формата используется как кандидат при пустом Backup-key suffix. Ручное значение используется без резервной попытки; неверный ключ останавливает обработку архива. Пароли и suffix остаются только в памяти для текущего модема между действиями и вкладками; при смене модема или закрытии программы они очищаются. В журнал они не записываются. Совпадение ключа само по себе не разрешает восстановление: проверяются архив, MD5, шаблон rc.local, USB-путь и неизменность остальных файлов. Сначала отправляется одна известная команда zwrt_bsp.usb.set mode=debug, если список методов подтверждает её или недоступен; при явном отсутствии команда пропускается. Только если root ADB не появился, сохраняется свежий зашифрованный бэкап и проверяется поддерживаемый шаблон. Название прошивки не заменяет проверку фактических данных. Восстановление отправляется один раз. Если точная строка включения уже есть, возможна одна штатная перезагрузка без восстановления."),
            new("3. Продолжение после обрыва",
                "Намерение сохраняется до запроса. Повторный запуск проверяет результат на том же модеме; уже отправленные USB debug, восстановление и перезагрузка не повторяются. Неизвестный результат сохраняет журнал для продолжения. Проверки CID, boot ID, root и соответствия устройства остаются обязательными для установки.")
        ]);

    public static OperationHelpTopic CleanPreparation { get; } = new(
        "Чистая установка после заводского сброса", "Подробно об очистке компонентов",
        "После заводского сброса переустанавливает агент и SSH с введённым новым паролем. Затем сохраняет проверенный архив компонентов программы и очищает их данные и временные файлы. Штатная прошивка, IMEI и SIM не сбрасываются. Флажок выключен по умолчанию; открытие справки ничего не меняет.",
        [
            new("Архив перед удалением",
                "Приложение сохраняет компоненты и их настройки в локальный архив в папке SetupBackups. Пока скачивание и контрольная сумма архива не подтверждены, удаление не начинается."),
            new("Что остаётся и что проверяется",
                "Очищаются компоненты VPN, его профили и настройки Wi-Fi с VPN; дополнительные страницы на экране модема, их выбор, порядок и раскладка; веб-панель агента и данные установщика агента. Сам агент, SSH-доступ и резервные копии подготовки остаются. IMEI, SIM и профили eSIM не меняются. Настройки TTL, локализация экрана, пользователи SSH, SSClash, диагностические утилиты и остальные штатные настройки сохраняются. Посторонние файлы и неподтверждённые изменения не удаляются; работающий VPN сначала нужно выключить. После очистки дополнительные компоненты можно установить заново соответствующими кнопками."),
            new("Продолжение после ошибки",
                "Подготовка и очистка имеют отдельные журналы. Если очистка прервана, кнопка продолжает только её: пароль агента не меняется повторно и установка SSH не запускается заново. При неизвестном результате журнал сохраняется."),
            new("Отмена до удаления",
                "Если удаление ещё не запрашивалось, кнопку «Отменить очистку» можно использовать после проверки того же модема по SSH. Это снимает только локальное намерение очистки; резервные копии и файлы модема остаются. Если удаление уже начато или состояние неизвестно, отмена запрещена. Например, после отмены можно вручную выключить Wi-Fi с VPN и затем снова выбрать очистку.")
        ]);

    public static OperationHelpTopic Preparation { get; } = new(
        "Как выполняется предварительная подготовка", "Подробно о предварительной подготовке модема", "Подготовка проверяет существующий SSH, затем root USB ADB. Если доступа нет, используются известная штатная USB-команда и, при необходимости, восстановление строго проверенного шаблона бэкапа. Открытие справки ничего не запускает.",
        [
            new("Проверка ключа без подготовки доступа",
                "Кнопка «Проверить ключ бэкапа» использует только пароль Web и необязательный ручной suffix. Она сохраняет свежий зашифрованный оригинал и идентичность локально, проверяет расшифровку, MD5 и структуру архива в памяти. Известный ключ формата проверяется как кандидат независимо от имени прошивки. Совпадение ключа и формата не разрешает восстановление, ADB, SSH или установку компонентов; для этих действий сохраняются отдельные проверки. Неверный ручной suffix не подменяется автоматическим. Расшифрованные файлы на диск не записываются."),
            new("1. Проверка доступа и модема",
                "Работающий выбранный SSH сохраняется без агента, Web-входа или установки. Незавершённая установка сначала требует продолжения своего журнала. Если SSH нет, проверяется root USB ADB; без Web допускается только доказанное единственное USB-устройство. При Web-входе USB должен совпасть с прочитанной идентичностью. Неверный пароль или изменение устройства останавливает подготовку. Готовый root ADB не зависит от ключа бэкапа."),
            new("2. Если доступа ещё нет",
                "Известный ключ формата используется как кандидат при пустом Backup-key suffix. Ручное значение используется без резервной попытки; неверный ключ останавливает обработку архива. Пароли и suffix остаются только в памяти для текущего модема между действиями и вкладками; при смене модема или закрытии программы они очищаются. В журнал они не записываются. Совпадение ключа само по себе не разрешает восстановление: проверяются архив, MD5, шаблон rc.local, USB-путь и неизменность остальных файлов. Порядок: штатный USB debug — затем проверенный бэкап. При недоступной интроспекции проверяется только одна известная команда, без подбора имён или паролей. Явно отсутствующий метод пропускается. До восстановления сохраняется зашифрованный оригинал и сверяется идентичность. Неизвестный шаблон отказывается до загрузки на модем."),
            new("3. Установка SSH и агента",
                "После появления доступа проверяются фактические root, Linux ARM64, CID, boot ID, файловая система, инструменты и механизм запуска. Профиль linux-arm64-access устанавливает пассивный агент discovery; названия прошивок не разрешают функции IMEI, eSIM radio или VPN. Хэши встроенных файлов, повторная идентификация, резервные копии и удалённые транзакции остаются обязательными."),
            new("4. Продолжение после обрыва",
                "Журнал setup-pending.json сохраняется до потенциальной записи. При повторном запуске проверяется та же операция и устройство; отправленные восстановление и установка не повторяются автоматически. Успех требует проверки установленного состояния и SSH. Пароли, Web-сессия и suffix не записываются в журнал.")
        ]);

    public static OperationHelpTopic Imei { get; } = new(
        "Как записываются оба IMEI",
        "Подробно о записи обоих IMEI",
        "Кнопка меняет два индекса NV550 через проверенные помощники DIAG/EFS. До первой записи приложение сохраняет исходные NV и EFS config на Windows, временно разрешает запись и после двух перезагрузок подтверждает итог. Это операция только для проверенной MU5250 B31; экспериментальная B02 остаётся режимом чтения IMEI.",
        [
            new("1. Доступ и ограничения",
                "Запись запускается только после подключения root SSH; эта кнопка сама не выполняет предварительную подготовку. SSH.NET использует локальный Ed25519 private key и точный host key из known_hosts, полученный при подготовке. Оба новых IMEI должны состоять из 15 цифр, иметь правильную контрольную цифру и различаться. Перед записью снова требуются точные SHA-256 прошивки MU5250 B31 и diag-router: галочка пропуска общей проверки не снимает этот запрет. Незавершённая подготовка или операция IMEI блокирует новую запись.",
                "%LOCALAPPDATA%\\ZTE IMEI Studio\\SSH\\id_ed25519\n%LOCALAPPDATA%\\ZTE IMEI Studio\\SSH\\known_hosts\nsha256sum /firmware/image/modem.b16 /usr/bin/diag-router"),
            new("2. Исходные данные и блокировки",
                "Приложение сверяет eMMC CID, хэши прошивки и boot_id. Оно берёт локальную imei-operation.lock, сохраняет токен в imei-lock.json и создаёт принадлежащую операции /tmp/zte-imei-app.lock на модеме. Помощник zte_nv читает оба 128-байтных индекса NV550; значения IMEI сравниваются с get_imei и get_imei2 штатного ubus API. Если предложенная пара уже записана, операция не начинается.",
                "cat /sys/block/mmcblk0/device/cid /proc/sys/kernel/random/boot_id\n<zte_nv> --snapshot\nubus call zwrt_zte_mdm.api get_imei\nubus call zwrt_zte_mdm.api get_imei2\n%LOCALAPPDATA%\\ZTE IMEI Studio\\imei-lock.json\n/tmp/zte-imei-app.lock"),
            new("3. Проверенные временные помощники",
                "Перед каждым вызовом встроенные zte_nv, zte_config и zte_config_read сверяются с Resources/Helpers/helpers.json. В приватный /tmp/zte-imei-<UUID> помощник передаётся по stdin SSH, получает права 700 и снова проверяется по SHA-256. Если нужен план, он передаётся отдельно и проверяется таким же образом. После вызова приложение пытается удалить только свой временный каталог. Эти помощники используют DIAG/EFS и не получают произвольные команды записи.",
                "mkdir /tmp/zte-imei-<UUID>\ncat > <tmp>/helper; chmod 700 <tmp>/helper; sha256sum <tmp>/helper\ncat > <tmp>/plan; sha256sum <tmp>/plan\n<tmp>/helper <проверенный-режим> <tmp>/plan"),
            new("4. Бэкап до первой записи",
                "zte_config_read читает /config внутри EFS модемного процессора — это не Linux-файл /config. Проверяется структура B31: 15 073 байта, 249 записей, CRC и исходное значение флага записи. Оба NV перечитываются, чтобы исключить изменение во время бэкапа. В Backups/IMEI/<UUID> сохраняются nv0.bin, nv1.bin, config.bin и manifest.json с SHA-256, IMEI и идентичностью устройства; приложение сразу открывает копию и проверяет её. Лишь затем создаётся imei-pending.json с целевыми полными NV. В каждом 128-байтном NV меняются только первые 9 байт кодировки IMEI; остальные 119 байт сохраняются. Этот бэкап не является полным образом модема.",
                "<zte_config_read> --read-config\n<zte_nv> --snapshot\n%LOCALAPPDATA%\\ZTE IMEI Studio\\Backups\\IMEI\\<UUID>\\nv0.bin\n%LOCALAPPDATA%\\ZTE IMEI Studio\\Backups\\IMEI\\<UUID>\\nv1.bin\n%LOCALAPPDATA%\\ZTE IMEI Studio\\Backups\\IMEI\\<UUID>\\config.bin\n%LOCALAPPDATA%\\ZTE IMEI Studio\\Backups\\IMEI\\<UUID>\\manifest.json\n%LOCALAPPDATA%\\ZTE IMEI Studio\\imei-pending.json"),
            new("5. Временный флаг и первая перезагрузка",
                "Из исходного config формируется кандидат: байт флага config102 по смещению 499 меняется с 0 на 1, CRC пересчитывается; прочие байты сохраняются. zte_config получает план «исходный + кандидат», включает разрешение записи через проверенные операции EFS и затем приложение повторно читает config. Стадия и время сохраняются до потенциально неоднозначного вызова. Штатная команда перезагрузки отправляется один раз; затем до четырёх минут ожидаются тот же модем и новый boot_id. Потеря SSH во время перезагрузки сама по себе не означает неудачу.",
                "<zte_config> --enable-flag <план-original+candidate>\nubus call zwrt_mc.device.manager device_reboot '{\"moduleName\":\"web\"}'"),
            new("6. Два индекса NV550 последовательно",
                "После загрузки проверяются config и оба NV: каждый должен совпадать с известным исходным либо целевым содержимым. Создаётся 512-байтный план из текущих NV0/NV1 и целевых NV0/NV1. Помощник zte_nv --apply-plan последовательно записывает индексы 0 и 1, сверяя данные после каждого шага; затем приложение отдельно перечитывает пару NV и оба значения ubus. Это не атомарная запись двух слотов. При сбое помощник может попытаться восстановить известные исходные записи, но при потере питания или связи результат требует проверки.",
                "<zte_nv> --apply-plan <план-512-байт>\n<zte_nv> --snapshot\nubus call zwrt_zte_mdm.api get_imei\nubus call zwrt_zte_mdm.api get_imei2"),
            new("7. Возврат config и заключительная проверка",
                "После подтверждения пары zte_config возвращает точный исходный EFS config, включая прежний флаг и CRC. Приложение сохраняет стадию final-reboot, один раз запрашивает вторую перезагрузку и ждёт нового boot_id того же модема. После неё проверяются NV, API и побайтное совпадение config с исходным. Только при полном успехе создаётся IMEIResults/<UUID>.json и удаляется imei-pending.json. В обычной новой операции ожидаются две перезагрузки; при продолжении уже выполненные шаги определяются по журналу и фактическому состоянию.",
                "<zte_config> --restore-original-config <план-original+candidate>\nubus call zwrt_mc.device.manager device_reboot '{\"moduleName\":\"web\"}'\n<zte_config> --check-original <план-original+candidate>\n%LOCALAPPDATA%\\ZTE IMEI Studio\\IMEIResults\\<UUID>.json"),
            new("8. Продолжение и восстановление пары",
                "Если операция прервалась, бэкап и imei-pending.json остаются. Кнопка «Продолжить незавершённую операцию» заново проверяет устройство, хэши бэкапа, текущие NV и config; неизвестное состояние останавливает автоматическую запись. После неопределённого вызова config приложение требует паузу не менее 210 секунд, после записи NV — 150 секунд, прежде чем разрешить повторную сверку. «Восстановить» в списке бэкапов использует тот же защищённый процесс и сперва сохраняет свежую копию текущего состояния; посторонние 119 байт обоих NV должны совпасть с выбранной копией. Операция не прошивает raw-разделы и не заменяет полный образ ZTEDATA.",
                "%LOCALAPPDATA%\\ZTE IMEI Studio\\imei-pending.json\n%LOCALAPPDATA%\\ZTE IMEI Studio\\Backups\\IMEI\\<UUID>\\manifest.json")
        ]);
}
